#!/usr/bin/env python3
"""trlite.py - a tiny `tr` clone for the common cases.

Usage: trlite.py [-d] [-s] SET1 [SET2]

Options:
  -d  delete characters in SET1 (SET2 must not be given)
  -s  squeeze repeated characters of SET1 (or SET2 when translating)

Sets support character ranges like a-z or A-Z.
Reads from stdin, writes to stdout.

Exit status: 0 on success, 2 on usage error.
"""

import sys


def parse_set(spec):
    """Expand a set specification like 'a-cx' into a list of characters."""
    out = []
    i = 0
    while i < len(spec):
        # Range like a-z (also handles literal '-' at start/end)
        if i + 2 < len(spec) and spec[i + 1] == "-":
            lo, hi = spec[i], spec[i + 2]
            if ord(lo) > ord(hi):
                raise ValueError(f"range endpoints out of order: {lo}-{hi}")
            out.extend(chr(c) for c in range(ord(lo), ord(hi) + 1))
            i += 3
        else:
            out.append(spec[i])
            i += 1
    return out


def squeeze(text, keep_chars):
    """Collapse runs of consecutive identical chars that are in keep_chars."""
    out = []
    prev = None
    for ch in text:
        if ch in keep_chars and prev == ch:
            continue
        out.append(ch)
        prev = ch
    return "".join(out)


def main():
    args = sys.argv[1:]
    delete = False
    squeeze_flag = False

    while args and args[0] in ("-d", "-s"):
        if args[0] == "-d":
            delete = True
        else:
            squeeze_flag = True
        args.pop(0)

    if not args:
        print("usage: trlite.py [-d] [-s] SET1 [SET2]", file=sys.stderr)
        return 2

    if len(args) > 2:
        print("usage: trlite.py [-d] [-s] SET1 [SET2]", file=sys.stderr)
        return 2

    try:
        set1 = parse_set(args[0])
    except ValueError as exc:
        print(f"trlite.py: {exc}", file=sys.stderr)
        return 2

    if delete:
        if len(args) != 1 or squeeze_flag is False and False:
            pass
        if len(args) != 1:
            print("usage: trlite.py -d SET1", file=sys.stderr)
            return 2
        to_delete = set(set1)
        text = sys.stdin.read()
        result = "".join(ch for ch in text if ch not in to_delete)
        if squeeze_flag:
            result = squeeze(result, to_delete)
    elif len(args) == 2:
        try:
            set2 = parse_set(args[1])
        except ValueError as exc:
            print(f"trlite.py: {exc}", file=sys.stderr)
            return 2
        table = {}
        for idx, ch in enumerate(set1):
            # tr repeats the last char of SET2 if SET1 is longer
            table[ch] = set2[min(idx, len(set2) - 1)]
        text = sys.stdin.read()
        result = "".join(table.get(ch, ch) for ch in text)
        if squeeze_flag:
            translated_targets = {table[c] for c in set1}
            result = squeeze(result, translated_targets)
    else:
        # Single set without -d: only valid with -s
        if not squeeze_flag:
            print("usage: trlite.py [-d] [-s] SET1 [SET2]", file=sys.stderr)
            return 2
        text = sys.stdin.read()
        result = squeeze(text, set(set1))

    sys.stdout.write(result)
    return 0


if __name__ == "__main__":
    sys.exit(main())

